local this = GUI


local  uIPanel_open_originFunc = this.UIPanel_Open
function GUI:UIPanel_Open(filePath,parent,baseUI,args,isMulti,callback,requireFun)
    local id = InfoManager.taskOutInfo:IsFinishPanelTask(filePath, args)
    if id then
        SL:SendLuaNetMsg(LuaMessageIdToSever.REQ_VIEW_PANEL_TASK,{panelId = id})
    end
    
    local closePanels = {
            "dev/outui/Recharge/Panel/KLRechargeActivity/KLRechargeActivityPanel",
            "dev/outui/Efficiency/Panel/KLEfficiencyNew/KLEfficiencyNewPanel",
            "dev/outui/ShapeShiftCard/Panel/KLShapeShiftCardMain/KLShapeShiftCardMainPanel",
            "dev/outui/ThreeEarnings/Panel/KLEarnings/KLEarningsPanel",
            "dev/outui/MountPreference/Panel/KLMountPreference/KLMountPreferencePanel",
            "dev/outui/MainActivity/Panel/KLMainActivity/KLMainActivityPanel",
            "dev/outui/MainRecharge/Panel/KLMainRecharge/KLMainRechargePanel"
        }
    for i=1,#closePanels do
        local panel = closePanels[i]
        if panel == filePath then
            if this.timer then
                SL:UnSchedule(this.timer)
                this.timer = nil
            end
            this.timer = SL:ScheduleOnce(0.1, function()
                SL.ShowMainPanel()
            end)
            return
        end
    end
    local showUITbl = SL:GetConfigTable("cfg_hideplayerUI")
    for _,v in pairs(showUITbl) do
        if filePath == v.command then
            local panel = GUI:GetUI("dev/ui/MainUI/Panel/KLUIPlayerInfo/KLUIPlayerInfoPanel")
            if panel then
                local t = GUI:DOAnchorPos(GUI:GetRectTransform(panel.view.root), Vector2.New(0, -1420),0.5)
                GUI:TweenSetOnComplete(t, function()
                end)
            end
        end
    end
    
    local panel = uIPanel_open_originFunc(this,filePath,parent,baseUI,args,isMulti,function(panel)
        if callback then
            callback(panel)
        end
        if GUI.SetCustomTextMaterial then
            --GUI:SetCustomTextMaterial(panel.view.root,"Material/FGFontMat.mat",true)
        end
    end,requireFun)
   
    return panel
end

local  uIPanel_close_originFunc = this.UIPanel_Close
function GUI:UIPanel_Close(filePath,uipanel,uipanelId,uipanels)
    local showUITbl = SL:GetConfigTable("cfg_hideplayerUI")
    for _,v in pairs(showUITbl) do
        if filePath == v.command then
            local panel = GUI:GetUI("dev/ui/MainUI/Panel/KLUIPlayerInfo/KLUIPlayerInfoPanel")
            if panel then
                if GUI.ResetCustomTextMaterial then
                    GUI:ResetCustomTextMaterial(panel.view.root,"Material/FGFontMat.mat",true)
                end
                local t = GUI:DOAnchorPos(GUI:GetRectTransform(panel.view.root), Vector2.New(0, 0),0.5)
                GUI:TweenSetOnComplete(t, function()

                end)
            end
        end
        
    end
    return uIPanel_close_originFunc(this,filePath,uipanel,uipanelId,uipanels)
end

local  item_updataData_originFunc = this.Item_UpdataData
function GUI:Item_UpdataData(control, luaTable)
    local cfgId = luaTable["itemid"]
    local serverId = luaTable["serverId"]
    local serverData = luaTable["serverData"]
    luaTable["clickControl"] = control
    --屏蔽数量1
    if luaTable.itemcount == 1 or luaTable.itemcount == "1" then
        luaTable.itemcount = ""
    end
    if not string.isNullOrEmpty(luaTable.itemcount) then
        luaTable.itemcount = GUIUtil.FormatNumber(luaTable.itemcount, true)
    end
    if luaTable.itemcustomcount == 1 or luaTable.itemcustomcount == "1" then
        luaTable.itemcustomcount = ""
    end
 
    if serverData then
        cfgId = serverData.cfgId and serverData.cfgId or cfgId
    end
    
    if cfgId and (serverData or serverId) then
        local isElement = InfoManager.elementInfo:IsElement(cfgId)
        if isElement then
            local path,itemCfg,inscale,pos,rotate,modelCfg
            itemCfg = SL:GetConfig("cfg_item",cfgId)
            ---@type cfg_model_charactor_column
            modelCfg = SL:GetConfig("cfg_model_charactor", itemCfg.shape[1])
            inscale = modelCfg.inscale
            pos = modelCfg.inposition
            rotate = modelCfg.inrotate
            path = InfoManager.elementInfo:GetElmentResPath(serverData,serverId)

            luaTable["src"] = path
            luaTable["mscale"] = string.format("%d,%d,%d",inscale,inscale,inscale)
            luaTable["mrotate"] = string.format("%d,%d,%d",rotate[1],rotate[2],rotate[3])
            luaTable["mpos"] = string.format("%d,%d,%d",pos[1],pos[2],pos[3] or 0)
            luaTable["itemid"] = 0
        end
    end
    SL:Log("Item_UpdataData",cfgId)
    item_updataData_originFunc(this,control, luaTable)
end

